					return () => { if (packs.delete(one.id)) onChange(); };
				},

				/**
				 *「自己发一条」:立刻发一条自己的滚动弹幕。这是**加法式**扩展,api.version 不变。
				 * 层被宿主全屏遮罩挡住时先排队,遮罩关掉后自动补发。
