			for (const prefix of prefixes) {
				if (t.startsWith(prefix)) return t.slice(prefix.length).trim();
			}
			return matchesDiveText(t, label) ? "" : null;
		}

		/**
		 * 观测通道(参考 deepseek-harness discussion #3669):把一批会话事件折叠成
		 * 「当前这一步的重试状态」纯函数。只认结构化事件,不做日志/文本推断 ——
		 * 没有可认的信号就返回 null,调用方什么都不显示(显式降级,绝不猜次数)。
		 *
		 *   llm/retry         → { retry, max, provider, code, delayMs }(dsh-llm-retry 发的)
		 *   llm/retry-started → 标记这次重试已经开始跑(started = true)
		 *   step/start|end、turn/start|end、assistant/message → 清空(该步/该回合翻篇了)
		 *
		 * entries 是客户端事件窗口的条目数组(`{ type: "event", event }` / transient);
		 * previous 是上一拍的状态(用于增量折叠)。provider / code 原样透传,
		 * 但 code 先过 safeObservationToken 脱敏。
		 */
		function retryStateFromEntries(entries, previous) {
			let state = previous && typeof previous === "object" ? { ...previous } : null;
			const list = Array.isArray(entries) ? entries : [];
			for (const entry of list) {
				const event = entry && entry.type === "event" ? entry.event : null;
				if (!event || typeof event.type !== "string") continue;
				const type = event.type;
				if (type === "step/start" || type === "step/end" || type === "turn/start" || type === "turn/end" || type === "assistant/message") {
					state = null;
					continue;
				}
				if (type === "llm/retry") {
					const d = event.data && typeof event.data === "object" ? event.data : {};
					const retry = Number.isFinite(d.retry) ? d.retry : null;
					if (retry === null || retry <= 0) continue;
					const failure = d.failure && typeof d.failure === "object" ? d.failure : {};
					state = {
						retry,
						max: Number.isFinite(d.maxRetries) && d.maxRetries > 0 ? d.maxRetries : null,
						provider: typeof d.provider === "string" ? d.provider : "",
						code: safeObservationToken(failure.code),
						delayMs: Number.isFinite(d.delayMs) && d.delayMs >= 0 ? d.delayMs : null,
						retryId: typeof d.retryId === "string" ? d.retryId : "",
						started: false,
					};
					continue;
				}
				if (type === "llm/retry-started" && state !== null) {
					const d = event.data && typeof event.data === "object" ? event.data : {};
					const id = typeof d.retryId === "string" ? d.retryId : "";
					// 只认同一串重试的 started:别的重试链 / 迟到事件不乱入
					if (state.retryId && id && state.retryId !== id) continue;
					state.started = true;
				}
			}
			return state;
		}

		/**
		 * 只放行像「短错误码」的 token(字母数字 + . _ : - ,≤32 字符)。
		 * provider 的失败报文可能夹带 URL / 路径 / 凭据,这类一律不显示 ——
		 * 对应讨论里「不得暴露 endpoints / paths / credentials」那条。
		 */
		function safeObservationToken(value) {
			if (typeof value !== "string") return "";
			const v = value.trim();
			if (v.length === 0 || v.length > 32) return "";
			return /^[A-Za-z0-9_.:-]+$/.test(v) ? v : "";
		}

		/**
		 * 按模板渲染观测徽标。state 为空 / 模板为空 → ""(不占位、不显示)。
		 * {max} 缺失时会顺手把模板里留下的孤立斜杠收掉("⟳ 3/" → "⟳ 3")。
		 */
		function retryBadgeText(state, template) {
			if (!state || !Number.isFinite(state.retry)) return "";
			const tpl = typeof template === "string" ? template : "";
			if (tpl.length === 0) return "";
			const map = {
				retry: String(state.retry),
				max: Number.isFinite(state.max) ? String(state.max) : "",
				provider: typeof state.provider === "string" ? state.provider : "",
				code: typeof state.code === "string" ? state.code : "",
				delay: Number.isFinite(state.delayMs) ? String(Math.round(state.delayMs / 1000 * 10) / 10) : "",
			};
			let out = tpl.replace(/\{(\w+)\}/g, (m, key) => (key in map ? map[key] : m));
			out = out.replace(/[·|,，、/\s]+$/, "").replace(/\s{2,}/g, " ").trim();
			return out;
		}

		/** 配置片段合并到默认配置(浅合并,gradient / title / danmaku 对象深合并) */
		function mergeConfig(base, over) {
			if (!over) return { ...base };
			const out = { ...base };
			for (const key of Object.keys(over)) {
				if ((key === "gradient" || key === "title" || key === "danmaku" || key === "whaleTailMotion" || key === "antiRepeat" || key === "appearance") && over[key] !== null && typeof over[key] === "object") {
					out[key] = { ...(base[key] || {}), ...over[key] };
				} else {
					out[key] = over[key];
				}
			}
			return out;
		}

		/** 预设列表归一化:[{ id, label?, config?, phrases? }];非法条目跳过,返回 null 表示无 */
		function normalizePresets(list) {
			if (!Array.isArray(list)) return null;
			const out = [];
			for (const item of list) {
				if (item === null || typeof item !== "object" || Array.isArray(item)) continue;
				if (typeof item.id !== "string" || item.id.length === 0) continue;
				const p = { id: item.id };
				if (typeof item.label === "string" && item.label.length > 0) p.label = item.label;
				else if (item.label !== null && typeof item.label === "object") {
					const lab = {};
					for (const k of ["zh", "en"]) {
						if (typeof item.label[k] === "string" && item.label[k].length > 0) lab[k] = item.label[k];
					}
					if (Object.keys(lab).length > 0) p.label = lab;
				}
				if (item.config !== undefined) {
					const c = normalizeConfig(item.config);
					if (c) p.config = c;
				}
				if (item.phrases !== undefined) {
					const t = normalizeTable(item.phrases);
					if (t) p.phrases = t;
				}
				out.push(p);
			}
			return out.length > 0 ? out : null;
		}

		/** 词库包列表归一化:[{ id, label?, phrases? }];非法/重复 id 跳过,返回 null 表示无 */
		function normalizePacks(list) {
			if (!Array.isArray(list)) return null;
			const out = [];
			const seen = new Set();
			for (const item of list) {
				if (item === null || typeof item !== "object" || Array.isArray(item)) continue;
				if (typeof item.id !== "string" || item.id.length === 0) continue;
				if (seen.has(item.id)) continue;
				seen.add(item.id);
				const p = { id: item.id };
				if (typeof item.label === "string" && item.label.length > 0) p.label = item.label;
				else if (item.label !== null && typeof item.label === "object") {
					const lab = {};
					for (const k of ["zh", "en"]) {
						if (typeof item.label[k] === "string" && item.label[k].length > 0) lab[k] = item.label[k];
					}
					if (Object.keys(lab).length > 0) p.label = lab;
				}
				if (item.phrases !== undefined) {
					const t = normalizeTable(item.phrases);
					if (t) p.phrases = t;
				}
				out.push(p);
			}
			return out.length > 0 ? out : null;
		}

		/**
		 * 合并两套语言表(bank 与 pack 形态均为 { zh: groups, en: groups } 或 null):
		 * 同语言同阶段按文本去重,先出现者优先(保核心库权重);合法阶段组缺失即跳过。
		 * 返回合并后的语言表;全空返回 null。
		 */
		function mergeGroups(bank, pack) {
			const out = {};
			for (const lang of ["zh", "en"]) {
				const a = (bank && bank[lang]) || null;
				const b = (pack && pack[lang]) || null;
				const merged = {};
				for (const phase of [PHASE_THINKING, PHASE_RUNNING, PHASE_LONG]) {
					const la = a && Array.isArray(a[phase]) ? a[phase] : [];
					const lb = b && Array.isArray(b[phase]) ? b[phase] : [];
					if (lb.length === 0) {
						if (la.length > 0) merged[phase] = la;
						continue;
					}
					const seen = new Set(la.map(entryText).filter(Boolean));
					const items = la.slice();
					for (const e of lb) {
						const t = entryText(e);
						if (t.length > 0 && !seen.has(t)) {
							seen.add(t);
							items.push(e);
						}
					}
					if (items.length > 0) merged[phase] = items;
				}
				if (Object.keys(merged).length > 0) out[lang] = merged;
			}
			return Object.keys(out).length > 0 ? out : null;
		}

		/**
		 * 词库包链式合并:bank 为核心库(或预设词库),packs 按顺序叠加;
		 * enabledIds 为 null 表示全部启用,否则只合并名单内的包。
		 */
		function mergePackChain(bank, packs, enabledIds) {
			if (!packs || packs.length === 0) return bank;
			const enabled = Array.isArray(enabledIds) ? new Set(enabledIds) : null;
			let out = bank;
			for (const p of packs) {
				if (enabled && !enabled.has(p.id)) continue;
				if (!p.phrases) continue;
				out = mergeGroups(out, p.phrases);
			}
			return out;
		}

		/** 词库包的语言与阶段:运行时只合并这两门语言 × 三个阶段(见 mergeGroups) */
		const PACK_LANGS = ["zh", "en"];
		const PACK_PHASES = [PHASE_THINKING, PHASE_RUNNING, PHASE_LONG];

		/**
		 * 词库包条目总数。langs/phases 省略 = 数所有语言与阶段(设置页的「N 条」);
		 * 传 PACK_LANGS / PACK_PHASES = 只数真正会进状态栏、且在编辑器里看得见的那部分。
		 */
		function packPhraseCount(pack, langs, phases) {
			if (!pack || !pack.phrases || typeof pack.phrases !== "object") return 0;
			const langList = Array.isArray(langs) ? langs : Object.keys(pack.phrases);
			let n = 0;
			for (const lang of langList) {
				const group = pack.phrases[lang];
				if (!group || typeof group !== "object") continue;
				const phaseList = Array.isArray(phases) ? phases : Object.keys(group);
				for (const phase of phaseList) {
					const list = group[phase];
					if (Array.isArray(list)) n += list.length;
				}
			}
			return n;
		}

		/** 只数 zh/en × 三个阶段:编辑器与状态栏真正用得到的部分 */
		function editablePhraseCount(pack) {
			return packPhraseCount(pack, PACK_LANGS, PACK_PHASES);
		}

		/**
		 * 核心词库为空时的自动落点(issue #144)。
		 *
		 * 运行时只合并 enabledPacks 里的包,所以落点必须优先选「启用中」的包 —— 否则用户
		 * 打的字会写进一个永远不会进状态栏的包:写盘成功、没有任何报错,状态栏却毫无变化。
		 * 启用包有多个时优先选**有内容**的那个(用户想编辑的通常是自己写过文案的包),
		 * 都没有内容再退回第一个启用包;一个包都没启用时同样优先有内容的(「打开就是空编辑区」
		 * 不该因为一个都没启用而更糟),并标记 enabled:false 供调用方提示。
		 *
		 * enabledIds 为 null(文档没写这个字段,或写了但整份无效)= 全部启用:
		 * 一律回到改动前的 packs[0] 落点,不在这条路径上顺手改行为。
		 */
		function pickFallbackPack(packs, enabledIds) {
			const list = Array.isArray(packs) ? packs.filter((p) => p && typeof p.id === "string") : [];
			if (list.length === 0) return null;
			// 文档没写(或写坏了)enabledPacks = 全部启用:保持改动前的 packs[0] 语义,不趁机换落点
			if (!Array.isArray(enabledIds)) return { id: list[0].id, enabled: true };
			const enabled = list.filter((p) => enabledIds.includes(p.id));
			// 一个包都没启用:优先有内容的包(「打开就是空编辑区」不该因为一个都没启用而更糟)
			if (enabled.length === 0) {
				const withPhrases = list.find((p) => editablePhraseCount(p) > 0);
				return { id: (withPhrases || list[0]).id, enabled: false };
			}
			return { id: (enabled.find((p) => editablePhraseCount(p) > 0) || enabled[0]).id, enabled: true };
		}

		// ══ 词库投稿(issue #151):在设置页里写完、本地按机器人同口径校验、一键开预填好的 Issue ══
		/**
		 * 投稿规则**与 scripts/phrase-bot.cjs 完全一致**。
		 *
		 * 为什么客户端再实现一份:投稿表单在 GitHub 上,校验结果要等机器人跑完才回来,而且
		 * 不合规的投稿会被机器人直接关掉。设置页里先按同一套规则预校验,用户当场就能改对。
		 * 两份实现必须同步 —— scripts/smoke-test.cjs 里有**对齐测试**:同一批输入分别喂给
		 * 这里和机器人,逐条比对"是否拒绝 / 拒绝原因"。
		 */
		const SUBMIT_MAX_PHRASE_LEN = 200;
		const SUBMIT_MAX_PHRASES = 60;
		const SUBMIT_MAX_TOTAL_ITEMS = 120;
		const SUBMIT_BANNED_HTML = /<\/?[a-zA-Z]/;
		const SUBMIT_BANNED_URL = /https?:\/\/|www\./i;
		const SUBMIT_BANNED_CTRL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/;
		const SUBMIT_BANNED_SEMICOLON = /[\u003b\uff1b\ufe54\u037e]/;
		const SUBMIT_AD_SOURCE = /(?:github\.com\/)?[A-Za-z0-9][A-Za-z0-9_.-]*\/[A-Za-z0-9][A-Za-z0-9_.-]*/;
		const SUBMIT_ELLIPSIS = "\u2026";
		const SUBMIT_COMMUNITY_PACK = "community";
		const SUBMIT_AD_PACK = "ads";
		const SUBMIT_TITLE = "词库投稿: 新文案";
		const SUBMIT_LABEL = "词库投稿";
		/** 正文要经 URL 传输;超过这个长度就只留「复制」通道(GitHub 会拒超长 URL) */
		const SUBMIT_URL_SAFE_MAX = 7000;
		/**
		 * 行首的 # / --- 只该出现在**正文结构**里:机器人的正文解析会把它们当注释/分隔线
		 * 丢掉(等于静默丢文案),`##` 级别的小节标题还会把「### 语种」等小节切碎。
		 * 这条**只在设置页生效**:GitHub 表单那边用户填不进这种行首,机器人不需要它。
		 */
		const SUBMIT_STRUCTURAL = /^\s*(#{1,6}(\s|$)|-{3,}$)/;

		/** 归一化单条文案:与 scripts/phrase-bot.cjs 的 normalizePhraseText 一字不差 */
		function submissionNormalizeText(raw) {
			let t = String(raw).trim().replace(/\t+/g, " ");
			t = t.replace(/\.{2,}/g, SUBMIT_ELLIPSIS);
			if (!t.endsWith(SUBMIT_ELLIPSIS)) t += SUBMIT_ELLIPSIS;
			return t;
		}

		/** 文案 textarea → 非空行(不过滤):校验要看得到"会被丢掉的行" */
		function submissionRawLines(text) {
			if (typeof text !== "string") return [];
			return String(text).split(/\r?\n/).map((l) => l.trim()).filter((l) => l.length > 0);
		}

		/** 真正会提交的行(与机器人 parsePhraseLines 同规则:丢掉 # 注释、``` 围栏、--- 分隔线) */
		function submissionLines(text) {
			return submissionRawLines(text).filter((l) =>
				!l.startsWith("#") && !l.startsWith("```") && !/^---+$/.test(l));
		}

		/** 语种选择 → ["zh"] / ["en"] / ["zh","en"] */
		function submissionLangs(token) {
			if (token === "both") return ["zh", "en"];
			if (token === "en") return ["en"];
			return ["zh"];
		}

		/** 分组选择 → ["thinking"] / ["running"] / ["long"] / 三阶段 */
		function submissionPhases(token) {
			if (token === "all") return ["thinking", "running", "long"];
			return ["thinking", "running", "long"].includes(token) ? [token] : ["thinking"];
		}

		/** 目标词库包 → 合法 id;非法/缺省 = 社区投稿包(与机器人 parsePackValue / applyToBank 同口径) */
		function submissionPackId(value) {
			const token = String(value == null ? "" : value).trim().split(/[\s（(]/)[0].toLowerCase();
			return /^[a-z0-9][a-z0-9-]*$/.test(token) ? token : SUBMIT_COMMUNITY_PACK;
		}

		/**
		 * 逐条校验。返回 { blocking: string[], errors: [{ text, probs: string[] }] }。
		 * blocking = 整体性问题(文案为空 / 超过条数上限),errors = 单条问题;
		 * probs 是**机器可读的原因码**(i18n 与对齐测试都用它,别改成中文串)。
		 */
		function submissionProblems(rawLines, opts) {
			const pack = submissionPackId(opts && opts.pack);
			const isAd = pack === SUBMIT_AD_PACK;
			const blocking = [];
			const errors = [];
			if (rawLines.length === 0) blocking.push("empty");
			if (rawLines.length > SUBMIT_MAX_PHRASES) blocking.push("tooMany");
			for (const raw of rawLines) {
				const probs = [];
				if (raw.length > SUBMIT_MAX_PHRASE_LEN) probs.push("tooLong");
				if (SUBMIT_BANNED_HTML.test(raw)) probs.push("html");
				if (SUBMIT_BANNED_URL.test(raw) && !isAd) probs.push("url");
				if (isAd && !SUBMIT_AD_SOURCE.test(raw)) probs.push("adSource");
				if (SUBMIT_BANNED_CTRL.test(raw)) probs.push("ctrl");
				if (SUBMIT_BANNED_SEMICOLON.test(raw)) probs.push("semicolon");
				if (SUBMIT_STRUCTURAL.test(raw)) probs.push("structural");
				if (probs.length > 0) errors.push({ text: raw, probs });
			}
			return { blocking, errors };
		}

		/**
		 * 展开 lang × phase × 文案,并按现有词库查重(与机器人 validateSubmission 同一套账):
		 * bankHas(lang, phase, text) 由调用方给(设置页用当前文档的词库,机器人用随包词库)。
		 * 返回 { items, duplicates, total }。
		 */
		function submissionItems(langs, phases, lines, bankHas) {
			const items = [];
			const seen = new Set();
			let duplicates = 0;
			for (const lang of langs) {
				for (const phase of phases) {
					for (const raw of lines) {
						const text = submissionNormalizeText(raw);
						const key = lang + "|" + phase + "|" + text;
						if (seen.has(key)) continue;
						seen.add(key);
						if (typeof bankHas === "function" && bankHas(lang, phase, text)) { duplicates += 1; continue; }
						items.push({ lang, phase, text });
					}
				}
			}
			return { items, duplicates, total: items.length + duplicates };
		}

		/**
		 * 投稿的完整判定(设置页与测试共用同一个结论,避免两处口径漂移):
		 * 逐条校验 + 展开查重 + 条数上限 + 须知勾选 → { blocking, errors, items, duplicates, ready }。
		 * blocking/errors 的原因码与机器人拒绝理由一一对应(见 smoke-test 的对齐测试)。
		 */
		function submissionReport(input) {
			const rawLines = Array.isArray(input.rawLines) ? input.rawLines : [];
			const pack = submissionPackId(input.pack);
			const check = submissionProblems(rawLines, { pack });
			const expanded = submissionItems(
				input.langs || [], input.phases || [], submissionLines(rawLines.join("\n")), input.bankHas);
			const blocking = check.blocking.slice();
			if (expanded.items.length > SUBMIT_MAX_TOTAL_ITEMS) blocking.push("tooManyTotal");
			// 须知没勾 = 机器人那句"未勾选「提交须知」复选框"
			if (!input.rules) blocking.push("rules");
			// 全部与现有词库重复 = 机器人那句"没有新增内容"(只在其它检查都通过时才这么判)
			if (check.blocking.length === 0 && check.errors.length === 0 && blocking.length === 0 && expanded.items.length === 0) {
				blocking.push("allDuplicate");
			}
			return {
				blocking,
				errors: check.errors,
				items: expanded.items,
				duplicates: expanded.duplicates,
				ready: blocking.length === 0 && check.errors.length === 0,
			};
		}

		/**
		 * 生成投给机器人的正文。小节标题与 GitHub 表单渲染出来的**完全一致**,
		 * 所以走的是 scripts/phrase-bot.cjs 的 parseBodyFallback 那条解析路径 —— 不依赖
		 * 表单字段,普通 Issue 也能被机器人正确处理(对齐测试直接拿机器人解析器验)。
		 */
		function buildSubmissionBody(input) {
			const langs = input.langs || [];
			const phases = input.phases || [];
			const langText = langs.length > 1 ? "zh + en (两种都要)" : langs[0] === "en" ? "en (English)" : "zh (中文)";
			const phaseText = phases.length > 1 ? "全部三阶段"
				: phases[0] === "running" ? "running (运行中)"
					: phases[0] === "long" ? "long (长时间任务)" : "thinking (刚开始)";
			const pack = submissionPackId(input.pack);
			const packLabel = input.packLabel ? " (" + input.packLabel + ")" : "";
