/** 拉一次上游词库:校验 → 只留 packs / phrases → 变了才原子写盘并立即生效;失败保留上一次成功词库 */
export declare function refreshRemoteBank(): Promise<{ ok: boolean; updated?: boolean; skipped?: string; error?: string }>;

