		await node.refreshRemoteBank();
		ok("内容没变不重复写盘", node.remoteBankStatus().updates === 1);
		stubFetch(JSON.stringify({ packs: [{ id: "deepseek", phrases: { zh: { thinking: ["上游 B…"] } } }] }));
		await node.refreshRemoteBank();
