		globalThis.fetch = async () => { throw new Error("offline"); };
		await node.refreshRemoteBank();
		ok("网络失败保留上一次成功词库", node.remoteBankStatus().lastError === "offline" && (await node.remoteBankDocument()).packs[0].phrases.zh.thinking[0] === "上游 B…");
		stubFetch("not json");
