ok("官方推荐速度默认 0.25,固定/TPS/随机和工具切换均按实际动作生效", (() => {
	for (const mode of ["fixed", "tps"]) {
		const motion = { enabled: true, animation: "official", mode, fixedSpeed: 6, tpsMaxSpeed: 10, tpsTiers: 5 };
		if (T.whaleTailWagFrequency(motion, 100000) !== 0.25) return false;
		if (T.whaleTailWagFrequency({ ...motion, animation: "random" }, 100000, 10, "official") !== 0.25) return false;
		if (T.whaleTailWagFrequency({ ...motion, animation: "wag" }, 100000, 10, "official") !== 0.25) return false;
		if (T.whaleTailWagFrequency(motion, 100000, 0.25, "wag") !== (mode === "fixed" ? 6 : 10)) return false;
		if (T.whaleTailWagFrequency({ ...motion, officialRecommendedSpeed: false }, 100000) !== (mode === "fixed" ? 6 : 10)) return false;
	}
	return T.DEFAULT_CONFIG.whaleTailMotion.officialRecommendedSpeed === true
		&& T.whaleTailWagFrequency({ enabled: false, animation: "official" }, 1000) === 0;
})());
ok("官方推荐开关在前后端及预设内一致校验", (() => {
	for (const value of [true, false, "true", 1, null]) {
		const config = { whaleTailMotion: { officialRecommendedSpeed: value } };
		const client = T.normalizeConfig(config)?.whaleTailMotion?.officialRecommendedSpeed;
		const doc = node.sanitizeConfigDocument({ config, presets: [{ id: "official", config }] });
		const expected = typeof value === "boolean" ? value : undefined;
		if (client !== expected || doc.config.whaleTailMotion?.officialRecommendedSpeed !== expected || doc.presets[0].config.whaleTailMotion?.officialRecommendedSpeed !== expected) return false;
	}
	return true;
})());
ok("旧配置缺少动作字段时仍使用原版翻摆", T.mergeConfig(T.DEFAULT_CONFIG, { whaleTailMotion: { enabled: true } }).whaleTailMotion.animation === "wag");
ok("工具触发默认关闭,概率边界与未命中不会误切换", (() => {
	const motion = { enabled: true, toolSwitchEnabled: true, toolSwitchChance: 0.35 };
	const forbidden = () => { throw new Error("Probability check should not draw"); };
	return T.DEFAULT_CONFIG.whaleTailMotion.toolSwitchEnabled === false
		&& T.shouldSwitchWhaleTailOnTool(motion, () => 0.349) === true
		&& T.shouldSwitchWhaleTailOnTool(motion, () => 0.35) === false
		&& T.shouldSwitchWhaleTailOnTool({ ...motion, toolSwitchChance: 1 }, forbidden) === true
		&& T.shouldSwitchWhaleTailOnTool({ ...motion, toolSwitchChance: 0 }, forbidden) === false
		&& T.shouldSwitchWhaleTailOnTool({ ...motion, enabled: false }, forbidden) === false
		&& T.shouldSwitchWhaleTailOnTool({ ...motion, toolSwitchEnabled: false }, forbidden) === false;
})());
ok("工具触发配置在前后端与预设中一致,非法值不保存", (() => {
	const input = { whaleTailMotion: { toolSwitchEnabled: true, toolSwitchChance: 2 } };
	const client = T.normalizeConfig(input).whaleTailMotion;
	const doc = node.sanitizeConfigDocument({ config: input, presets: [{ id: "tool", config: input }] });
	const bad = { whaleTailMotion: { toolSwitchEnabled: "yes", toolSwitchChance: NaN } };
	return client.toolSwitchEnabled === true && client.toolSwitchChance === 1
		&& doc.config.whaleTailMotion.toolSwitchChance === 1 && doc.presets[0].config.whaleTailMotion.toolSwitchChance === 1
		&& T.normalizeConfig(bad)?.whaleTailMotion === undefined
		&& node.sanitizeConfigDocument({ config: bad }).config.whaleTailMotion === undefined
		&& T.normalizeConfig({ whaleTailMotion: { toolSwitchChance: -1 } }).whaleTailMotion.toolSwitchChance === 0;
})());
ok("工具调用只计入新事件,忽略历史、分页、重复与参数流", (() => {
	const event = (seq, callId = "call-" + seq) => ({ type: "event", event: { type: "tool/call", seq, data: { callId, name: "bash" } } });
	const tracker = T.createToolCallTracker();
	if (tracker(null) !== 0 || tracker({ entries: [event(10)] }) !== 0) return false;
	const next = { entries: [event(10), event(11), event(11)], change: { kind: "append" } };
	if (tracker(next) !== 1 || tracker(next) !== 0) return false;
	if (tracker({ entries: [event(1), event(11)], change: { kind: "prepend" } }) !== 0) return false;
	if (tracker({ entries: [event(20)], change: { kind: "replace" } }) !== 0) return false;
	if (tracker({ entries: [{ type: "transient", event: { type: "assistant/live-chunk", seq: 20.5, data: { chunk: { type: "tool-call-delta" } } } }], change: { kind: "append" } }) !== 0) return false;
	if (tracker({ entries: [event(21), event(22)], change: { kind: "append" } }) !== 2) return false;
	return T.createToolCallTracker()({ entries: [event(100)] }) === 0;
})());
ok("动作配置在前后端及预设中一致,非法值不会落盘", (() => {
	for (const animation of ["wag", "sway", "twist", "official", "random"]) {
		const input = { whaleTailMotion: { animation } };
		if (T.normalizeConfig(input).whaleTailMotion.animation !== animation) return false;
		const doc = node.sanitizeConfigDocument({ config: input, presets: [{ id: "motion", config: input }] });
		if (doc.config.whaleTailMotion.animation !== animation || doc.presets[0].config.whaleTailMotion.animation !== animation) return false;
	}
	return T.normalizeConfig({ whaleTailMotion: { enabled: true, animation: "unknown" } }).whaleTailMotion.animation === undefined
		&& node.sanitizeConfigDocument({ config: { whaleTailMotion: { animation: "unknown" } } }).config.whaleTailMotion === undefined;
})());
ok("随机动作覆盖四种动作,并且不会连续重复", (() => {
	const actions = ["wag", "sway", "twist", "official"];
	const seen = new Set();
	for (const previous of actions) for (const random of [0, 0.49, 0.99]) {
		const next = T.pickWhaleTailAnimation("random", previous, () => random);
		if (!actions.includes(next) || next === previous) return false;
		seen.add(next);
	}
	return seen.size === 4 && T.pickWhaleTailAnimation("twist", "wag") === "twist";
})());
ok("动作池在前后端及预设里去重、过滤非法值,空池安全回退", (() => {
	for (const randomActions of [["official", "wag", "official", "bad"], [], ["random"], ["twist"]]) {
		const input = { whaleTailMotion: { randomActions, tpsMaxSpeed: 99 } };
		const client = T.normalizeConfig(input).whaleTailMotion;
		const doc = node.sanitizeConfigDocument({ config: input, presets: [{ id: "pool", config: input }] });
		if (JSON.stringify(client) !== JSON.stringify(doc.config.whaleTailMotion)
			|| JSON.stringify(client) !== JSON.stringify(doc.presets[0].config.whaleTailMotion)) return false;
		if (client.tpsMaxSpeed !== 10) return false;
	}
	return JSON.stringify(T.whaleTailRandomActions({ randomActions: [] })) === '["wag"]';
})());
ok("随机切换只抽取选中动作,单动作不会越出池子", (() => {
	const pool = ["official", "sway"];
	for (const previous of ["official", "sway", "wag"]) for (const random of [0, 0.99]) {
		const next = T.pickWhaleTailAnimation("random", previous, () => random, pool);
		if (!pool.includes(next) || next === previous) return false;
	}
	return T.pickWhaleTailAnimation("random", "official", () => 0.99, ["official"]) === "official";
})());
ok("6 帧衔接保留两端轮廓,相反绕向及起点不会导致轮廓折叠", (() => {
	const from = "M0 0 L20 0 L20 20 L0 20 Z";
	const to = "M30 20 L30 0 L10 0 L10 20 Z";
	const frames = T.whaleTailBridgeFrames(from, to);
	if (frames.length !== 6 || frames[0] !== from || frames[5] !== to || new Set(frames).size !== 6) return false;
	return frames.slice(1, -1).every((frame, index) => {
		const values = frame.match(/-?\d+(?:\.\d+)?/g).map(Number);
		const xs = values.filter((_, i) => i % 2 === 0), ys = values.filter((_, i) => i % 2 === 1);
		return Math.min(...xs) === (index + 1) * 2 && Math.max(...xs) === 20 + (index + 1) * 2
			&& Math.min(...ys) === 0 && Math.max(...ys) === 20;
	});
})());
// issue #144:核心词库为空时的自动落点必须选「启用中」的包 —— 运行时只合并 enabledPacks,
// 落到未启用的包上就是「打字写盘成功、状态栏永远不显示」(用户只会以为文案没保存)。
// 浏览器回归页(scripts/issue-144-disabled-pack-test.html)负责整条链路,这里守纯函数与文案。
console.log("== 自动落点只选启用中的词库包(issue #144)==");
(() => {
	const withPhrases = (id, texts) => ({ id, phrases: { zh: { thinking: texts } } });
	const A = withPhrases("reverse-proxy", []);          // 未启用、且本来就没有内容(报告人的那个包)
	const B = withPhrases("slacking", ["摸鱼一句"]);      // 启用中、有内容
	ok("只启用第二个包 → 落到第二个(不再无脑 packs[0])",
		JSON.stringify(T.pickFallbackPack([A, B], ["slacking"])) === '{"id":"slacking","enabled":true}',
		JSON.stringify(T.pickFallbackPack([A, B], ["slacking"])));
	ok("两个包都启用 → 优先有内容的那个(用户想编辑的通常是自己写过的包)",
		T.pickFallbackPack([A, B], ["reverse-proxy", "slacking"]).id === "slacking");
	ok("两个都启用但都空 → 退回第一个启用包",
		T.pickFallbackPack([withPhrases("a", []), withPhrases("b", [])], ["a", "b"]).id === "a");
	ok("一个包都没启用 → 优先有内容的包,并标记为未启用(设置页据此提示,不许静默)",
		JSON.stringify(T.pickFallbackPack([A, B], [])) === '{"id":"slacking","enabled":false}'
		&& JSON.stringify(T.pickFallbackPack([{ id: "a", phrases: {} }, { id: "b", phrases: {} }], [])) === '{"id":"a","enabled":false}');
	ok("文档没写 enabledPacks(= 全部启用)→ 保持改动前的 packs[0] 语义",
		T.pickFallbackPack([A, B], null).id === "reverse-proxy");
	ok("enabledPacks 里的 id 在 packs 里不存在 → 不选中不存在的包",
		T.pickFallbackPack([A, B], ["ghost"]).id === "slacking");
	ok("没有词库包 → null(调用方不设置编辑目标)",
		T.pickFallbackPack([], ["a"]) === null && T.pickFallbackPack(null, []) === null);
	ok("脏数据不抛异常", T.pickFallbackPack([null, { id: "x" }, {}, "y"], ["x"]).id === "x");
	ok("「有内容」只认编辑器和状态栏真会用的 zh/en × 三个阶段(issue #144;非该范围的不算)",
		T.pickFallbackPack([{ id: "ja-only", phrases: { ja: { thinking: ["x"] } } }, { id: "zh-ok", phrases: { zh: { thinking: ["y"] } } }], ["ja-only", "zh-ok"]).id === "zh-ok"
		&& T.pickFallbackPack([{ id: "idle-only", phrases: { zh: { idle: ["x"] } } }, { id: "ok", phrases: { en: { long: ["y"] } } }], ["idle-only", "ok"]).id === "ok");
	ok("词库包条目数按内容算(全量口径:跨语言跨阶段)",
		T.packPhraseCount({ phrases: { zh: { thinking: ["a"] }, en: { running: ["b", "c"] } } }) === 3
		&& T.packPhraseCount({ phrases: {} }) === 0 && T.packPhraseCount(null) === 0);
	ok("设置页「N 条」与自动落点分别是全量 / 可用口径(两者不互相污染)",
		T.packPhraseCount({ phrases: { zh: { thinking: ["a"], idle: ["b"] }, ja: { thinking: ["c"] } } }) === 3
		&& T.editablePhraseCount({ phrases: { zh: { thinking: ["a"], idle: ["b"] }, ja: { thinking: ["c"] } } }) === 1
		&& JSON.stringify(T.PACK_LANGS) === '["zh","en"]');
	const clientSrc = fs.readFileSync(path.join(__dirname, "..", "lib", "client.js"), "utf8");
	// 只在设置页字典区里数(packs.disabled 这类键在别处也可能出现),按中文/英文各一条核对
	const dictHead = clientSrc.indexOf("const SETTINGS_DICTS = {");
	const dictTail = clientSrc.indexOf("\n\t\t\t};", dictHead);
	const dictRegion = dictHead < 0 ? "" : clientSrc.slice(dictHead, dictTail > 0 ? dictTail : dictHead + 40000);
	const dictValues = (key) => {
		// 值里可能有转义引号(英文那条引号包着包名),所以按 " 转义规则取值
		const re = new RegExp('"' + key.replace(/\./g, "\\.") + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"', "g");
		const out = [];
		for (const entry of dictRegion.match(re) || []) {
			const from = entry.indexOf(': "') + 3;
			out.push(entry.slice(from, -1).replace(/\\"/g, '"').replace(/\\\\/g, "\\"));
		}
		return out;
	};
	for (const key of ["packs.disabled", "packs.disabledWarning"]) {
		const values = dictValues(key);
		ok(`设置页文案 ${key} 中英都有`, values.length >= 2 && values.every((v) => v.length > 0), JSON.stringify(values));
	}
	const warnValues = dictValues("packs.disabledWarning");
	ok("未启用提示说清后果(中文含「状态栏」/ 英文含 status line)且带 {name} 占位",
		warnValues.some((v) => v.includes("状态栏") && v.includes("{name}"))
		&& warnValues.some((v) => v.includes("status line") && v.includes("{name}")),
		JSON.stringify(warnValues));
	ok("自动落点用共享纯函数(不再内联写 packs[0])",
		/if \(target === "" && coreEmpty && !fallbackDoneRef\.current\) \{\s*\n\s*fallbackDoneRef\.current = true;\s*\n\s*const pick = pickFallbackPack\(/.test(clientSrc));
	ok("自动落点只在首次读盘做一次(用户选了默认词库后重读不被顶走)",
		clientSrc.includes("const fallbackDoneRef = react.useRef(false);"));
	ok("启用名单按运行时同一口径归一化(非字符串项 = 整份无效 = 全部启用)",
		clientSrc.includes("rawEnabled.every((s) => typeof s === \"string\" && s.length > 0)")
		&& clientSrc.includes("const effectiveEnabled = enabledList ? enabledList.slice() : packIds;"));
})();

// issue #151:投稿界面搬进设置页。真正的价值在"本地先校验、且与机器人**同口径**":
// 用户在设置页里改对,就不会投稿后等半天被机器人关掉。这一节同时钉住三件事:
//   ① 客户端规则与 scripts/phrase-bot.cjs 逐条一致(防止两边漂移);
//   ② 生成的正文能被**机器人自己的解析器**读懂(一键投稿的根据);
//   ③ 预填 URL 里的正文与"复制"出来的正文是同一份。
console.log("== 设置页投稿:与机器人同口径 + 正文可被机器人解析(issue #151)==");
(() => {
	// 客户端代码在文件开头已用 vm 沙箱加载成 T(__test),这里直接用 —— 不要再 require:
	// lib/client.js 是浏览器形态(靠 window.__ModuleLoader__ 注册),node 里 require 会抛。
	const bot2 = require("./phrase-bot.cjs");

	// ── ① 归一化与字段解析:与机器人逐一对照 ──
	const corpusNorm = ["写代码中...", "深潜中", "a		b", " 前后空格 ", "多个....点", "末尾已是…", "；分号", "emoji 🐳 收尾"];
	ok("单条归一化与机器人一致(fixPhrase 口径)",
		corpusNorm.every((x) => T.submissionNormalizeText(x) === bot2.normalizePhraseText(x)));

	// 设置页的下拉值 ↔ 表单选项文本,成对喂给两边,解析结果必须一致
	ok("语种解析与机器人一致",
		[["zh", "zh (中文)"], ["en", "en (English)"], ["both", "zh + en (两种都要)"], ["en", "English"], ["zh", "中文"]]
			.every(([token, formText]) => JSON.stringify(T.submissionLangs(token)) === JSON.stringify(bot2.parseLangValue(formText))));
	const phaseCases = [["thinking", "thinking (刚开始)"], ["running", "running (运行中)"], ["long", "long (长时间任务)"], ["all", "全部三阶段"]];
	ok("分组解析与机器人一致",
		phaseCases.every(([token, text]) => JSON.stringify(T.submissionPhases(token)) === JSON.stringify(bot2.parsePhaseValue(text))));
	const packCases = ["community (社区投稿 · 默认)", "star-ask (求 star 文案)", "ads", "不合法!!", ""];
	ok("目标包解析与机器人一致",
		packCases.every((x) => T.submissionPackId(x) === bot2.parsePackValue(x)),
		packCases.map((x) => x + "→" + T.submissionPackId(x)).join(" | "));

	// ── ② 逐条校验:同一批输入,两边"是否拒绝"必须一致(客户端还多一条正文结构检查) ──
	const ruleCases = [
		"正常一条文案",
		"把两条串一起;第二条",              // 分号
		"<b>html</b> 注入",                  // HTML
		"看这里 https://example.com/x",      // 链接
		"带控制字符\u0007的",               // 控制字符
		"x".repeat(201),                     // 超长
		"多个....点会被归一化",              // 应当通过
	];
	const bank0 = { phrases: {}, packs: [] };
	const mismatches = [];
	for (const line of ruleCases) {
		const mine = T.submissionProblems([line], { pack: "community" });
		const botSub = bot2.parseSubmission({ lang: ["zh"], phase: ["thinking"], phrases: line, rules: ["x"] }, "");
		const botRes = bot2.validateSubmission(botSub, bank0);
		const mineRejected = mine.errors.length > 0;
		const botRejected = !botRes.ok;
		if (mineRejected !== botRejected) mismatches.push(line.slice(0, 20) + " 客户端=" + mineRejected + " 机器人=" + botRejected);
	}
	ok("逐条校验的「是否拒绝」与机器人一致", mismatches.length === 0, mismatches.join(" | "));

	// 原因码与机器人拒绝理由对得上(抽查三类)
	const semicolonCase = T.submissionProblems(["a;b"], { pack: "community" });
	ok("分号被标为 semicolon",
		semicolonCase.errors.length === 1 && semicolonCase.errors[0].probs.includes("semicolon"));
	ok("非 ads 包的链接被标为 url;ads 包放行链接但要求出处",
		T.submissionProblems(["see https://a.com"], { pack: "community" }).errors[0].probs.includes("url")
		&& T.submissionProblems(["see https://a.com"], { pack: "ads" }).errors[0].probs.includes("adSource")
		&& T.submissionProblems(["上线了,顺手点个 star… github.com/o/r"], { pack: "ads" }).errors.length === 0);

	// ── ③ 整体判定:空 / 未勾须知 / 超行数 / 展开超上限 / 全重复 ──
	const rep = (input) => T.submissionReport(Object.assign({ rawLines: ["a"], langs: ["zh"], phases: ["thinking"], pack: "community", rules: true }, input));
	ok("文案为空 → empty", rep({ rawLines: [] }).blocking.includes("empty"));
	ok("未勾须知 → rules 且不就绪", (() => { const r = rep({ rules: false }); return r.blocking.includes("rules") && r.ready === false; })());
	ok("超过 60 行 → tooMany", rep({ rawLines: Array.from({ length: 61 }, (_, i) => "第" + i + "条") }).blocking.includes("tooMany"));
	ok("展开超过 120 条 → tooManyTotal",
		rep({ rawLines: Array.from({ length: 60 }, (_, i) => "第" + i + "条"), langs: ["zh", "en"], phases: ["thinking", "running", "long"] }).blocking.includes("tooManyTotal"));
	ok("全部与现有词库重复 → allDuplicate",
		rep({ rawLines: ["已有的一条…"], bankHas: (l, p, t) => t === "已有的一条…" }).blocking.includes("allDuplicate"));
	ok("部分重复:重复的计入 duplicates、不阻断其余",
		(() => { const r = rep({ rawLines: ["已有的一条…", "新的…"], bankHas: (l, p, t) => t === "已有的一条…" }); return r.duplicates === 1 && r.items.length === 1 && r.ready === true; })());
	ok("就绪时 ready=true 且条数正确(zh,thinking,2 行 → 2 条)",
		(() => { const r = rep({ rawLines: ["甲", "乙"] }); return r.ready === true && r.items.length === 2 && r.items[0].text === "甲…"; })());

	// ── ④ 生成的正文必须能被机器人自己解析并校验通过(一键投稿的根据) ──
	const bank = { phrases: {}, packs: [{ id: "community", label: { zh: "社区投稿", en: "Community" }, phrases: { zh: { thinking: [] } } }] };
	const cases = [
		{ name: "中文/thinking/社区包", input: { langs: ["zh"], phases: ["thinking"], pack: "community", packLabel: "社区投稿", lines: ["正在努力翻找答案…", "深潜中,可能有点久…"], name: "小测" }, expect: { langs: "zh", phases: "thinking", pack: "community", n: 2, name: "小测" } },
		{ name: "双语×三阶段", input: { langs: ["zh", "en"], phases: ["thinking", "running", "long"], pack: "slacking", packLabel: "摸鱼", lines: ["甲…", "乙…"], name: "" }, expect: { langs: "zh,en", phases: "thinking,running,long", pack: "slacking", n: 2, name: "" } },
		{ name: "英文/long", input: { langs: ["en"], phases: ["long"], pack: "coding", packLabel: "写代码", lines: ["Still thinking…"], name: "someone" }, expect: { langs: "en", phases: "long", pack: "coding", n: 1, name: "someone" } },
	];
	const bodyFails = [];
	for (const c of cases) {
		const body = T.buildSubmissionBody(c.input);
		const sub = bot2.parseSubmission(undefined, body);
		const res2 = bot2.validateSubmission(sub, bank);
		const got = { langs: sub.langs.join(","), phases: sub.phases.join(","), pack: sub.pack, n: sub.phrases.length, name: sub.name };
		if (JSON.stringify(got) !== JSON.stringify(c.expect) || !res2.ok || res2.items.length === 0) {
			bodyFails.push(c.name + ": " + JSON.stringify(got) + " ok=" + res2.ok + " expect=" + JSON.stringify(c.expect));
		}
	}
	ok("机器人能解析设置页生成的正文(语种/分组/包/条数/署名逐项一致)且校验通过",
		bodyFails.length === 0, bodyFails.join(" | "));
	ok("正文带「### 语种」小节 —— 工作流的触发条件之一(不依赖表单字段)",
		T.buildSubmissionBody(cases[0].input).includes("### 语种"));
	ok("正文带已勾选的提交须知(- [x]),机器人据此判定 confirmed",
		bot2.parseSubmission(undefined, T.buildSubmissionBody(cases[0].input)).confirmed === true);
	ok("ads 包正文同样能被机器人接受",
		(() => {
			const b = T.buildSubmissionBody({ langs: ["zh"], phases: ["running"], pack: "ads", lines: ["正在写代码,顺手点个 star… github.com/01Virex/dsh-status-rotator"] });
			const r2 = bot2.validateSubmission(bot2.parseSubmission(undefined, b), bank);
			return r2.ok === true && r2.items.length === 1;
		})());
	ok("署名留空时正文仍是 _No response_(与表单渲染一致),机器人解析出空署名",
		(() => {
			const b = T.buildSubmissionBody({ langs: ["zh"], phases: ["thinking"], pack: "community", lines: ["甲…"], name: "" });
			return b.includes("_No response_") && bot2.parseSubmission(undefined, b).name === "";
		})());

	// ── ⑤ 预填 URL:指向本仓库 issues/new,且正文与"复制"的是同一份 ──
	const body0 = T.buildSubmissionBody(cases[0].input);
	const url0 = T.buildSubmissionUrl(body0);
	ok("URL 指向仓库的 issues/new", url0.startsWith("https://github.com/01Virex/dsh-status-rotator/issues/new?"));
	ok("URL 带 title / body / labels(标签=词库投稿)", (() => {
		const q = new URLSearchParams(url0.slice(url0.indexOf("?") + 1));
		return q.get("title") === "词库投稿: 新文案" && q.get("labels") === "词库投稿"
			&& q.get("body") === body0
			&& bot2.parseSubmission(undefined, q.get("body")).langs.join() === "zh";
	})());
	ok("正文过 URL 编解码后逐字不变(含换行与中文)", (() => {
		const q = new URLSearchParams(url0.slice(url0.indexOf("?") + 1));
		return q.get("body") === body0 && body0.includes("\n");
	})());
	ok("超长判定用的是 URL 实际长度(阈值 " + T.SUBMIT_URL_SAFE_MAX + ")",
		(() => {
			const short = T.buildSubmissionUrl(T.buildSubmissionBody({ langs: ["zh"], phases: ["thinking"], pack: "community", lines: ["甲…"] }));
			const long = T.buildSubmissionUrl(T.buildSubmissionBody({ langs: ["zh", "en"], phases: ["thinking", "running", "long"], pack: "community", lines: Array.from({ length: 60 }, (_, i) => "第" + i + "条很长的文案,用来把 URL 撑过阈值") }));
			return short.length <= T.SUBMIT_URL_SAFE_MAX && long.length > T.SUBMIT_URL_SAFE_MAX;
		})());

	// ── ⑥ 只在设置页生效的结构检查:会被正文解析丢掉的行首 ──
	ok("行首 # / --- 在设置页被拦下(机器人那边是静默丢弃)",
		T.submissionProblems(["# 注释"], { pack: "community" }).errors[0].probs.includes("structural")
		&& T.submissionProblems(["---"], { pack: "community" }).errors[0].probs.includes("structural")
		&& T.submissionProblems(["### 伪造小节"], { pack: "community" }).errors[0].probs.includes("structural"));
	ok("submissionLines 的过滤口径与机器人 parsePhraseLines 一致",
		(() => {
			const text = "甲…\n\n# 注释\n```\n乙…\n---\n丙…";
			return JSON.stringify(T.submissionLines(text)) === JSON.stringify(bot2.parsePhraseLines(text));
		})());
})();

