// issue #94:宿主模块系统在工厂体跑完后会把**当下所有没有 `data-plugin` 的 <style>** 认到自己名下
// (`@deepseek-ai/dsh-client-modules` 的 claimStyles),并在自己 revision 变化时用 removeOwnedStyles
// 删掉名下的标签 —— 未声明归属的样式于是会被后物化的模块认领走、随它一次变更一起消失
// (症状:设置页整套样式没了,重启有时又好)。浏览器回归页负责行为断言,这里再加一道静态契约。
console.log("== 样式归属(data-plugin,issue #94)==");
(() => {
	const src = fs.readFileSync(path.join(__dirname, "..", "lib", "client.js"), "utf8");
	const creations = src.match(/createElement\("style"\)/g) || [];
	const helperAt = src.indexOf("const createOwnedStyle =");
	const helper = helperAt < 0 ? "" : src.slice(helperAt, helperAt + 600);
	ok("lib/client.js 只在 createOwnedStyle 里建 <style>", creations.length === 1 && helperAt > 0,
		`createElement("style") 出现 ${creations.length} 次`);
	ok("createOwnedStyle 建完就声明 data-plugin", helper.includes('setAttribute("data-plugin"') && helper.includes("STYLE_OWNER_ID"));
	ok("全部样式标签都走 createOwnedStyle(一个都不能漏)",
		["dsh-status-rotator-layout-style", "dsh-status-rotator-style", "dsh-status-rotator-danmaku-style", "dsh-status-rotator-settings-style", "dsh-status-rotator-whale-wag-style"]
			.every((id) => src.includes(`createOwnedStyle("${id}")`)));
	// dsh 0.2.0 尾巴摇动:24 帧 `d:path()` 关键帧约 50KB,不能塞进每次加载都注入的 layout 样式,
	// 否则从没开过摇动的用户也要付这份解析开销。行为断言在浏览器回归页。
	const layoutAt = src.indexOf("layoutStyleEl.textContent =");
	const layoutEnd = src.indexOf("appendChild(layoutStyleEl)", layoutAt);
	const layoutCss = layoutAt < 0 || layoutEnd < 0 ? "" : src.slice(layoutAt, layoutEnd);
	ok("摇动关键帧不在无条件注入的 layout 样式里(默认页面不背这 50KB)",
		layoutCss.length > 500 && !layoutCss.includes("TAIL_POSES"));
	ok("摇动关键帧改由按需注入的 owned <style> 承载,并在卸载 / 回合结束时回收",
		src.includes('createOwnedStyle("dsh-status-rotator-whale-wag-style")')
		&& src.includes("const ensureWhaleWagStyle") && src.includes("const releaseWhaleWagStyle")
		&& src.includes("whaleWagStyleEl.isConnected) whaleWagStyleEl.remove();"));
	ok("归属 id = 包名(与宿主自带插件同一套:dataset.plugin = 包名)",
		src.includes('const STYLE_OWNER_ID = "dsh-status-rotator"'));
	// 宿主 0.2.0-rc.2 的 runningIcon 里真正可见的是 span.runningWhaleAnimated(APNG mask),
	// svg.runningWhaleStill 只是被宿主 @supports/@media 关掉的静态回退。摇动若只藏 >svg,
	// 命中的正是那个已经 display:none 的死元素,宿主图标留在原地与 morph 轮廓叠成两条鲸鱼。
	// 这里钉住「藏掉除 morph 外的全部直接子级」,防止有人把选择器改回只针对 svg 的窄写法。
	ok("摇动样式藏掉除 morph 外的全部直接子级(宿主 APNG span 也要藏)",
		src.includes(".${TAIL_WAG_CLASS}>*:not(.${TAIL_MORPH_CLASS}){visibility:hidden}")
		&& !src.includes(".${TAIL_WAG_CLASS}>svg:not(.${TAIL_MORPH_CLASS}){visibility:hidden}"));
})();

// 投稿机器人的 JSON 哨兵:JSON.parse 对重复键是静默的(后一个覆盖前一个),
// 而「分支落后于 main → 人工解 config.example.json 的 JSON 冲突」正是重复键的来源:
// 两边的内容都塞进同一个 zh 对象,就得到 running/long 各两份 —— 解析不报错、条目悄悄少一半。
// issue #87:turnLabels 曾是唯一「只 set、从不 delete/clear」的容器,每个回合留一个
// 已脱离 DOM 的标签元素。运行时行为由浏览器回归页的 ?case=leak 断言;这里再加一道
// 廉价的静态契约,防止有人**删掉**某个容器的清理路径(冒烟测不到 DOM 生命周期)。
console.log("== 状态行:每回合容器的清理契约(issue #87)==");
(() => {
	const src = fs.readFileSync(path.join(__dirname, "..", "lib", "client.js"), "utf8");
	// 名字固定的一份清单:新增容器时也该在这里登记
	const containers = ["adopted", "typists", "lastPicks", "liveTemplates", "liveTimers",
		"lineButtons", "turnLabels", "turnLines", "turnPhases", "watchedButtons"];
	for (const name of containers) {
		const writes = (src.match(new RegExp("\\b" + name + "\\.(set|add)\\(", "g")) || []).length;
		const clears = (src.match(new RegExp("\\b" + name + "\\.(delete|clear)\\(", "g")) || []).length;
		ok(`容器 ${name}:有写入就必须有清理路径`, writes === 0 || clears > 0, `set/add=${writes} delete/clear=${clears}`);
	}
	// turnLabels 与 turnLines 的 key 都是折叠头按钮:释放回合时必须一起删
	ok("releaseStatusLine 同时清掉 turnLines 与 turnLabels(对称)", (() => {
		const body = src.slice(src.indexOf("const releaseStatusLine = (line) => {"));
		const end = body.indexOf("log(\"released status line\")");
		const chunk = body.slice(0, end);
		return chunk.includes("turnLines.delete(button)") && chunk.includes("turnLabels.delete(button)");
	})());
	ok("插件卸载时按按钮索引的容器也会被清空", (() => {
		const churn = src.slice(src.indexOf("adopted.clear();"));
		return churn.includes("turnLabels.clear()") && churn.includes("turnLines.clear()");
	})());
})();

